package cn.zhuatech.iot.controller; import cn.zhuatech.iot.common.ApiResponse; import cn.zhuatech.iot.dto.IotDto.*; import cn.zhuatech.iot.service.IotService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DEVICE_MANAGER','QUALITY','ADMIN')") public class IoTAdminController {private final IotService iot;public IoTAdminController(IotService iot){this.iot=iot;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(iot.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<DeviceTaskView>> orders(){return ApiResponse.ok(iot.deviceTasks());}}
